CREATE OR REPLACE FUNCTION public.activate_accountant(p_employee_id text, p_mobile text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_employee public.employees%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select e.* into v_employee
  from public.employees e
  join public.profiles p on p.id = e.profile_id
  where lower(trim(e.employee_id)) = lower(trim(p_employee_id))
    and regexp_replace(coalesce(p.phone,''),'[^0-9]','','g') = regexp_replace(coalesce(p_mobile,''),'[^0-9]','','g')
    and lower(coalesce(e.department,'')) in ('finance','accounts','account','fee','fees')
  limit 1;

  if v_employee.id is null then
    raise exception 'Finance verification failed';
  end if;

  update public.profiles
     set school_id = v_employee.school_id,
         updated_at = now()
   where id = auth.uid();

  insert into public.user_roles(user_id, school_id, role)
  values (auth.uid(), v_employee.school_id, 'accountant'::public.app_role)
  on conflict do nothing;

  return v_employee.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_parent(p_parent_code text, p_mobile text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_parent public.parents%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select p.* into v_parent
  from public.parents p
  where lower(trim(p.guardian_code)) = lower(trim(p_parent_code))
    and regexp_replace(coalesce(p.registered_mobile,''),'[^0-9]','','g') = regexp_replace(coalesce(p_mobile,''),'[^0-9]','','g')
  limit 1;

  if v_parent.id is null then raise exception 'Parent verification failed'; end if;

  update public.profiles
    set school_id = v_parent.school_id,
        updated_at = now()
  where id = auth.uid();

  insert into public.user_roles(user_id, school_id, role)
  values (auth.uid(), v_parent.school_id, 'parent'::public.app_role)
  on conflict do nothing;

  return v_parent.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_teacher(p_employee_id text, p_mobile text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_teacher public.teachers%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select t.* into v_teacher
  from public.teachers t
  where lower(trim(t.employee_id)) = lower(trim(p_employee_id))
    and regexp_replace(coalesce(t.registered_mobile,''),'[^0-9]','','g') = regexp_replace(coalesce(p_mobile,''),'[^0-9]','','g')
  limit 1;

  if v_teacher.id is null then raise exception 'Teacher verification failed'; end if;

  update public.profiles
    set school_id = v_teacher.school_id,
        updated_at = now()
  where id = auth.uid();

  insert into public.user_roles(user_id, school_id, role)
  values (auth.uid(), v_teacher.school_id, 'teacher'::public.app_role)
  on conflict do nothing;

  return v_teacher.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_school_role(p_user_id uuid, p_school_id uuid, p_role app_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.current_user_has_any_role(array['super_admin'::public.app_role,'school_admin'::public.app_role]) then
    raise exception 'Not authorized to assign roles';
  end if;

  if p_role = 'super_admin'::public.app_role and not public.current_user_has_role('super_admin'::public.app_role) then
    raise exception 'Only super admin can assign super admin';
  end if;

  insert into public.user_roles(user_id, school_id, role)
  values (p_user_id, p_school_id, p_role)
  on conflict do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_public_rls()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  cmd record;
begin
  for cmd in select * from pg_event_trigger_ddl_commands()
  loop
    if cmd.schema_name = 'public' and cmd.object_type in ('table','partitioned table') then
      execute format('alter table %s enable row level security', cmd.object_identity);
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_student_for_class_teacher(p_full_name text)
 RETURNS TABLE(student_id uuid, admission_no text, roll_no text, class_id uuid, section_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_teacher_id uuid;
  v_school_id uuid;
  v_year_id uuid;
  v_class_id uuid;
  v_section_id uuid;
  v_first_name text;
  v_middle_name text;
  v_last_name text;
  v_student_id uuid;
  v_admission_no text;
  v_roll_no text;
  v_next_admission bigint;
  v_next_roll bigint;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF trim(coalesce(p_full_name, '')) = '' THEN
    RAISE EXCEPTION 'Student name is required';
  END IF;

  v_teacher_id := app_private.current_teacher_id();
  IF v_teacher_id IS NULL OR NOT app_private.is_teacher() THEN
    RAISE EXCEPTION 'Teacher access required';
  END IF;

  SELECT t.school_id INTO v_school_id
  FROM public.teachers t
  WHERE t.id = v_teacher_id;

  SELECT ay.id INTO v_year_id
  FROM public.academic_years ay
  WHERE ay.school_id = v_school_id AND ay.is_current = true
  ORDER BY ay.start_date DESC
  LIMIT 1;

  SELECT a.class_id, a.section_id INTO v_class_id, v_section_id
  FROM public.teacher_subject_assignments a
  WHERE a.teacher_id = v_teacher_id
    AND a.academic_year_id = v_year_id
    AND a.is_class_teacher = true
  LIMIT 1;

  IF v_class_id IS NULL THEN
    RAISE EXCEPTION 'This teacher is not assigned as a class teacher';
  END IF;

  -- Serialize admission/roll generation per school.
  PERFORM pg_advisory_xact_lock(hashtext(v_school_id::text || ':student-register'));

  SELECT COALESCE(MAX(substring(s.admission_no from 'KC-ST-([0-9]+)')::bigint), 0) + 1
  INTO v_next_admission
  FROM public.students s
  WHERE s.school_id = v_school_id
    AND s.admission_no ~ '^KC-ST-[0-9]+$';

  v_admission_no := 'KC-ST-' || lpad(v_next_admission::text, 3, '0');

  SELECT COALESCE(MAX(e.roll_no::bigint), 0) + 1
  INTO v_next_roll
  FROM public.enrollments e
  WHERE e.academic_year_id = v_year_id
    AND e.class_id = v_class_id
    AND (e.section_id IS NOT DISTINCT FROM v_section_id)
    AND e.roll_no ~ '^[0-9]+$';

  v_roll_no := v_next_roll::text;

  v_first_name := split_part(trim(p_full_name), ' ', 1);
  v_last_name := CASE
    WHEN array_length(regexp_split_to_array(trim(p_full_name), '\s+'), 1) > 1
    THEN (regexp_split_to_array(trim(p_full_name), '\s+'))[array_length(regexp_split_to_array(trim(p_full_name), '\s+'), 1)]
    ELSE NULL
  END;
  v_middle_name := NULL;

  INSERT INTO public.students (
    school_id, admission_no, roll_no, first_name, middle_name, last_name,
    admission_date, status
  ) VALUES (
    v_school_id, v_admission_no, v_roll_no, v_first_name, v_middle_name, v_last_name,
    current_date, 'active'
  )
  RETURNING id INTO v_student_id;

  INSERT INTO public.enrollments (
    student_id, academic_year_id, class_id, section_id, roll_no, status
  ) VALUES (
    v_student_id, v_year_id, v_class_id, v_section_id, v_roll_no, 'active'
  );

  RETURN QUERY SELECT v_student_id, v_admission_no, v_roll_no, v_class_id, v_section_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.teacher_assessment_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.teacher_assessment_validate_marks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  assessment_max numeric(8, 2);
begin
  select a.maximum_marks into assessment_max
  from public.teacher_assessments a
  where a.id = new.assessment_id;

  if assessment_max is null then
    raise exception 'Assessment not found.';
  end if;
  if new.marks_obtained < 0 or new.marks_obtained > assessment_max then
    raise exception 'Marks must be between zero and the assessment maximum.';
  end if;
  if not public.teacher_assessment_student_is_enrolled(new.assessment_id, new.student_id) then
    raise exception 'Student is not actively enrolled in this assessment class and section.';
  end if;

  new.updated_by := (select auth.uid());
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.teacher_assessment_validate_maximum()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1
    from public.teacher_assessment_marks m
    where m.assessment_id = new.id
      and m.marks_obtained > new.maximum_marks
  ) then
    raise exception 'Maximum marks cannot be lower than marks already entered.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_teacher_phone(p_registered_mobile text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  updated_rows integer;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required.';
  end if;
  if p_registered_mobile is not null and length(p_registered_mobile) > 40 then
    raise exception 'Phone number must be 40 characters or fewer.';
  end if;

  update public.teachers
  set registered_mobile = nullif(btrim(p_registered_mobile), '')
  where profile_id = (select auth.uid());

  get diagnostics updated_rows = row_count;
  if updated_rows = 0 then
    raise exception 'Teacher profile was not found for this login.';
  end if;
  if updated_rows > 1 then
    raise exception 'More than one teacher profile is linked to this login.';
  end if;
end;
$function$
